from pathlib import Path
import re
path = Path("client/src/pages/ProfileFull.tsx")
text = path.read_text(encoding="utf-8")
pattern = re.compile(r"  const save = async \(\) => \{\n    if \(!token\) \{\n      pushError\([^\n]*\);\n      return;\n    \n*    const fd = new FormData\(\);\n    fd\.append\('display_name', displayName\);\n    fd\.append\('bio', bio\);\n    fd\.append\('city', city\.trim\(\)\);\n    if \(avatarFile\) fd\.append\('avatar', avatarFile\);\n    if \(bannerFile\) fd\.append\('banner', bannerFile\);\n\n    const res = await fetch\(resolveApiUrl\('/api/life/profile'\), \{\n      method: 'POST',\n      headers: \{ Authorization: `Bearer \${token}` \},\n      body: fd\n    \}\);\n\n    if \(!res\.ok\) \{ alert\('[^']*'\); return; \}\n    await load\(\);\n    setOpenEdit\(false\);\n    alert\('[^']*'\);\n  \};\n", re.MULTILINE)
replacement = "  const save = async () => {\n    if (!token) {\n      pushError('�� ������� ��������� �������: ��������� �����������');\n      return;\n    }\n    const fd = new FormData();\n    const trimmedCity = city.trim();\n    const trimmedProfileUrl = profileUrl.trim();\n    const mainColor = ensureFrameColor(avatarMainColor);\n    const miniColor = ensureFrameColor(avatarMiniColor);\n    fd.append('display_name', displayName);\n    fd.append('bio', bio);\n    fd.append('city', trimmedCity);\n    fd.append('profile_url', trimmedProfileUrl);\n    fd.append('avatar_frame_main_style', avatarMainStyle);\n    fd.append('avatar_frame_main_color', mainColor);\n    fd.append('avatar_frame_mini_style', avatarMiniStyle);\n    fd.append('avatar_frame_mini_color', miniColor);\n    if (avatarFile) fd.append('avatar', avatarFile);\n    if (bannerFile) fd.append('banner', bannerFile);\n\n    const res = await fetch(resolveApiUrl('/api/life/profile'), {\n      method: 'POST',\n      headers: { Authorization: `Bearer ${token}` },\n      body: fd\n    });\n\n    if (!res.ok) { alert('�������� ����������'); return; }\n    await load();\n    requestProfileRefresh();\n    setOpenEdit(false);\n    alert('������ �������!');\n  };\n"
new_text, count = pattern.subn(replacement, text)
if count == 0:
    raise SystemExit('save block not found via regex')
path.write_text(new_text, encoding="utf-8")
